style.css:
@-moz-document domain("youtube.com") {
/* Main content centered and classic width */
  ytd-app {
    max-width: 1200px !important;
    margin: 0 auto !important;
    background: #f9f9f9 !important;
  }

  /* Background like 2016 */
  body {
    background: #f1f1f1 !important;
  }

  /* Top bar in classic gray */
  ytd-masthead, #masthead-container {
    background-color: #e6e6e6 !important;
    box-shadow: none !important;
  }

  /* Remove Create button, Shorts, Stories, etc */
  #buttons ytd-button-renderer,
  ytd-shorts-shelf-renderer,
  ytd-reel-shelf-renderer,
  ytd-reel-item-renderer,
  ytd-mini-guide-entry-renderer[aria-label="Shorts"],
  ytd-mini-guide-entry-renderer[aria-label="Explore"],
  ytd-rich-section-renderer[section-identifier="shorts-shelf"] {
    display: none !important;
  }

  /* Sidebar: slim like 2016 */
  ytd-guide-renderer {
    background-color: #f8f8f8 !important;
    border-right: 1px solid #ccc !important;
  }

  /* Classic font */
  * {
    font-family: Roboto, Arial, sans-serif !important;
    font-size: 14px !important;
  }

  /* Video page layout tweaks */
  ytd-watch-flexy {
    --ytd-watch-flexy-max-width: 960px !important;
    margin: 0 auto !important;
  }

  /* Hide modern junk under video */
  ytd-merch-shelf-renderer,
  ytd-live-chat-frame,
  ytd-button-renderer.style-scope.ytd-menu-renderer {
    display: none !important;
  }

  /* Classic red progress bar */
  .ytp-play-progress {
    background-color: #cc181e !important;
  }

  /* Hide "More Actions" menu on hover */
  #menu button[aria-label="More actions"] {
    display: none !important;
  }

  /* Video player classic look */
  .html5-video-player {
    border: 1px solid #ccc !important;
    border-radius: 0 !important;
  }

  /* Logo tweak (optional) */
  #logo-icon {
    filter: grayscale(100%) brightness(0.8);
  }

  /* Remove rounded buttons and pills */
  tp-yt-paper-button,
  ytd-toggle-button-renderer,
  ytd-subscribe-button-renderer {
    border-radius: 0 !important;
  }
}
